import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";

const files = {
  registry: new URL("../src/prompt-blueprint.js", import.meta.url),
  history: new URL("../src/history-store.js", import.meta.url),
  imageGeneration: new URL("../src/image-generation.js", import.meta.url),
  outputStorage: new URL("../src/output-storage.js", import.meta.url),
  promptRenderer: new URL("../src/prompt-renderer.js", import.meta.url),
  app: new URL("../app.js", import.meta.url),
  output: new URL("../app.bundle.js", import.meta.url),
  index: new URL("../index.html", import.meta.url)
};

const [registrySource, historySource, imageGenerationSource, outputStorageSource, promptRendererSource, appSource, indexSource] = await Promise.all([
  readFile(files.registry, "utf8"),
  readFile(files.history, "utf8"),
  readFile(files.imageGeneration, "utf8"),
  readFile(files.outputStorage, "utf8"),
  readFile(files.promptRenderer, "utf8"),
  readFile(files.app, "utf8"),
  readFile(files.index, "utf8")
]);

function removeExports(source) {
  return source.replace(/^export\s+/gm, "");
}

const appWithoutImports = appSource.replace(/^import\s+.+?;\s*$/gm, "").trimStart();
const bundle = `/* Generated by scripts/build-browser-bundle.mjs. Edit app.js or src/, then rebuild. */
(() => {
"use strict";

${removeExports(registrySource)}
${removeExports(historySource)}
${removeExports(imageGenerationSource)}
${removeExports(outputStorageSource)}
${removeExports(promptRendererSource)}
${appWithoutImports}
})();
`;

const cacheKey = createHash("sha256").update(bundle).digest("hex").slice(0, 12);
const bundleScriptPattern = /(<script\s+src=["']app\.bundle\.js)(?:\?v=[^"']*)?(["']><\/script>)/;
if (!bundleScriptPattern.test(indexSource)) throw new Error("index.html 缺少 app.bundle.js 脚本入口");
const nextIndexSource = indexSource.replace(bundleScriptPattern, `$1?v=${cacheKey}$2`);
const writes = [writeFile(files.output, bundle)];
if (nextIndexSource !== indexSource) writes.push(writeFile(files.index, nextIndexSource));
await Promise.all(writes);
console.log(`Built app.bundle.js?v=${cacheKey}`);
